for f, pairs in FIX.items():
    s = open(f, encoding="utf-8").read()
    for old, new in pairs:
        n = s.count(old)
        if old == "<-":
            assert n > 0, f"{f}: no arrows"
        else:
            assert n == 1, f"{f}: found {n} times: {old[:70]!r}"
        s = s.replace(old, new)
    open(f, "w", encoding="utf-8", newline="").write(s)
    print("fixed", f)
